INSERT INTO `wp_olthem_email_templates` VALUES (1,'cr├®ation_atelier','atelier_admin','Demande d\'atelier re├ºue','L\'utilisateur [USERNAME] vient de cr├®er une demande de programmation d\'atelier.\r\n\r\nLieu de l\'├®v├®nement : [LIEU]\r\n\r\nTh├®matique de l\'atelier : [THEMATIQUE]\r\nP├®riode de programmation souhait├®e : entre le [start_date] et le [end_date]\r\nNombre de participants estim├® : +[nb_participants]\r\n\r\nPersonne de contact : [prenom] [nom]\r\nAdresse e-mail : [email]\r\nT├®l├®phone : [telephone]','2026-04-15 00:11:21'),(2,'reset_password','reset_password','Othem - R├®initialisation de mot de passe','Bonjour [prenom] [nom],\r\n\r\nVous avez demand├® la r├®initialisation de votre mot de passe.\r\nCliquez sur le lien suivant pour choisir un nouveau mot de passe (valable 1 heure) :\r\n\r\n[RESET_LINK]\r\n\r\nSi vous n\'├¬tes pas ├á l\'origine de cette demande, ignorez cet email.','2026-04-15 15:12:43');
