fd987fce66012a3e8807207e1e681b51','{{unknown}}'),(285,41,'_oembed_781dc9c9457e95e3dca86f9ac4557b96','{{unknown}}'),(286,41,'Builder_0_subsection_0_videolink','https://www.youtube.com/watch?v=Ljad--oYCd4&t=3s'),(287,41,'_Builder_0_subsection_0_videolink','field_69c4cdb278524'),(288,41,'Builder_0_subsection_0_videotitle','Titre de la vid├®o'),(289,41,'_Builder_0_subsection_0_videotitle','field_69c4d22f9fcaa'),(290,41,'Builder_0_subsection_0_videotext','Texte d\'accompagnement de la vid├®o'),(291,41,'_Builder_0_subsection_0_videotext','field_69c4d26e9fcab'),(292,41,'Builder_0_subsection_0_displayvideotitle','0'),(293,41,'_Builder_0_subsection_0_displayvideotitle','field_69c4d2a89fcac'),(294,41,'Builder_0_subsection_0_displayvideotext','0'),(295,41,'_Builder_0_subsection_0_displayvideotext','field_69c4d2c99fcad'),(296,41,'Builder_0_subsection_1_text','Salut, moi cÔÇÖest Olga !\r\n\r\n<em>Dans cette soci├®t├® de lÔÇÖimm├®diatet├® et de lÔÇÖinformation, je dois avouer que je me sens parfois un peu perdue. Qui sont ces algorithmes qui dictent ma pens├®e ou qui me disent quelle musique ├®couter? Est-ce que je fais encore des choix sur Internet? Parfois, je me sens un peu enferm├®e dans une bulle. JÔÇÖai lÔÇÖimpression quÔÇÖon me balance que ce que jÔÇÖaime. Au final, je dois la quitter ou pas ma bulle?┬á</em>JÔÇÖy suis bien, moi, dans ma bulle, avec mes potes, on se comprend...'),(297,41,'_Builder_0_subsection_1_text','field_69c4d54bbf536'),(298,41,'Builder_0_subsection_1_persotext','1'),(299,41,'_Builder_0_subsection_1_persotext','field_69c4d8e087a6b'),(300,41,'Builder_0_subsection_3_paragraphename','L\'├®mission radio !'),(301,41,'_Builder_0_subsection_3_paragraphename','field_69c72efc6a921'),(302,41,'Builder_0_subsection_4_text','Interviews compl├¿tes :'),(303,41,'_Builder_0_subsection_4_text','field_69c4d54bbf536'),(304,41,'Builder_0_subsection_4_persotext','0'),(305,41,'_Builder_0_subsection_4_persotext','field_69c4d8e087a6b'),(306,41,'Builder_0_subsection_5_audiotitle','Martin Culot, M├®dia - animation'),(307,41,'_Builder_0_subsection_5_audiotitle','field_69c72f5043368'),(308,41,'Builder_0_subsection_5_audiofile','69'),(309,41,'_Builder_0_subsection_5_audiofile','field_69c72f7243369'),(310,41,'Builder_0_subsection_7_videolink','https://www.youtube.com/watch?v=SN1zrUHnIW8&t=3s'),(311,41,'_Builder_0_subsection_7_videolink','field_69c4cdb278524'),(312,41,'Builder_0_subsection_7_videotitle','Titre de la vid├®o'),(313,41,'_Builder_0_subsection_7_videotitle','field_69c4d22f9fcaa'),(314,41,'Builder_0_subsection_7_videotext','Texte d\'accompagnement de la vid├®o'),(315,41,'_Builder_0_subsection_7_videotext','field_69c4d26e9fcab'),(316,41,'Builder_0_subsection_7_displayvideotitle','0'),(317,41,'_Builder_0_subsection_7_displayvideotitle','field_69c4d2a89fcac'),(318,41,'Builder_0_subsection_7_displayvideotext','0'),(319,41,'_Builder_0_subsection_7_displayvideotext','field_69c4d2c99fcad'),(320,41,'Builder_0_subsection_8_paragraphename','Le cycle d\'ateliers'),(321,41,'_Builder_0_subsection_8_paragraphename','field_69c72efc6a921'),(324,41,'Builder_0_subsection_9_text','Que se passe-t-il derri├¿re lÔÇÖ├®cran entre le moment o├╣ nous terminons de regarder une vid├®o et celui o├╣ Youtube ou Netflix nous en propose une nouvelle ? Comment Spotify fait-il pour d├®terminer les artistes ou les chansons qui pourraient nous plaire ? Les algorithmes de recommandation sont au coeur des plateformes num├®riques d├®livrant des contenus commerciaux, culturels et informationnels et fa├ºonnent lÔÇÖenvironnement m├®diatique contemporain. Malgr├® leur influence sur les pratiques m├®diatiques, ils restent largement opaques pour les utilisateurs qui nourrissent espoirs et peurs les concernant.\r\n\r\nAction M├®dias Jeunes propose aux participant.e.s de r├®pondre eux-m├¬mes ├á ces questions en cr├®ant un algorithme de recommandation sur papier ├á partir de donn├®es concernant des vid├®os en ligne et leurs audiences. Les participant.e.s se confrontent ├á leurs repr├®sentations ├á propos des algorithmes tout en appr├®hendant certains principes de base du fonctionnement des syst├¿mes algorithmiques.\r\n\r\nCette animation peut notamment sÔÇÖinscrire dans le cadre dÔÇÖun cours de math├®matiques.\r\n\r\nD├ëTAILS PRATIQUES\r\n<ul>\r\n 	<li>Dur├®e : entre 2 et 4 heures de cours</li>\r\n 	<li>Nombre : de 6 ├á 25 jeunes</li>\r\n 	<li>Besoin particulier : une salle de classe ou au Mundaneum</li>\r\n 	<li>Prix: gratuit!</li>\r\n</ul>\r\nInformation et r├®servation : gaetan.santarelli@mundaneum.be'),(325,41,'_Builder_0_subsection_9_text','field_69c4d54bbf536'),(326,41,'Builder_0_subsection_9_persotext','0'),(327,41,'_Builder_0_subsection_9_persotext','field_69c4d8e087a6b'),(328,41,'Builder_0_subsection_10_paragraphename','Dossier p├®dagogique'),(329,41,'_Builder_0_subsection_10_paragraphename','field_69c72efc6a921'),(330,41,'Builder_0_subsection_11_iframe','http:////v.calameo.com/?bkcode=00634963984dbda74f71f&language=fr&page=&showsharemenu=true&clickTo=embed&clickTarget=_self&clickToUrl=&autoFlip=0&mode=mini&wmode=transparent'),(331,41,'_Builder_0_subsection_11_iframe','field_69c73cf3282d9'),(340,39,'Builder_0_subsection','a:4:{i:0;s:9:\"imagesolo\";i:1;s:8:\"textbloc\";i:2;s:15:\"paragraphetitle\";i:3;s:6:\"iframe\";}'),(341,39,'_Builder_0_subsection','field_69c4c745e4070'),(342,39,'Builder','a:1:{i:0;s:10:\"subsection\";}'),(343,39,'_Builder','field_69aef24b28175'),(344,39,'_oembed_914d5aa0a2989e9a4940eaea62811f34','{{unknown}}'),(345,39,'_oembed_eb20ff9e9e7e3d622398c5153d34cea8','{{unknown}}'),(346,39,'Builder_0_subsection_0_image','51'),(347,39,'_Builder_0_subsection_0_image','field_69cbb59ba2b3d'),(348,39,'Builder_0_subsection_0_imagescale','1.5'),(349,39,'_Builder_0_subsection_0_imagescale','field_69cbb647a2b3e'),(350,39,'Builder_0_subsection_0_xoffset','0'),(351,39,'_Builder_0_subsection_0_xoffset','field_69cbb685a2b3f'),(352,39,'Builder_0_subsection_0_yoffset','50'),(353,39,'_Builder_0_subsection_0_yoffset','field_69cbb6b2a2b40'),(354,39,'Builder_0_subsection_1_text','Cette th├®matique propose de prendre ├á bras-le-corps une question qui traverse notre ├®poque et nos usages num├®riques : la polarisation des opinions sur les r├®seaux sociaux, et la rarification progressive de la nuance dans les d├®bats en ligne.Il sÔÇÖint├¿gre au projet ÔÇ£On nÔÇÖa que lÔÇÖinfo quÔÇÖon se donne!ÔÇØ port├® par le Mundaneum et la Club de la presse du Hainaut-Mons et sÔÇÖarticule autour dÔÇÖun objectif simple mais ambitieux : recr├®er des espaces de dialogue, dÔÇÖ├®coute et de pens├®e critique. Prendre le temps de ralentir, dans un environnement qui pousse ├á r├®agir vite, fort, parfois sans recul.\r\n\r\nCar si les r├®seaux sociaux promettaient ├á leurs d├®buts un nouvel ├óge du d├®bat d├®mocratique, un lieu ouvert o├╣ chacun┬Àe pourrait sÔÇÖexprimer, se confronter aux id├®es des autres et tisser des liens, force est de constater quÔÇÖils alimentent aujourdÔÇÖhui des logiques oppos├®es. Scandales, clashs et polarisations id├®ologiques y occupent une place centrale, encourag├®s par des algorithmes qui r├®compensent lÔÇÖengagement ├®motionnel plut├┤t que lÔÇÖ├®change raisonn├®.Ce ph├®nom├¿ne de polarisation ne r├®sulte pas uniquement dÔÇÖun glissement culturel ou dÔÇÖune radicalisation des opinions : il est aussi le fruit dÔÇÖune ├®conomie de lÔÇÖattention.\r\n\r\nDans ce mod├¿le, chaque clic, chaque like, chaque commentaire, quÔÇÖil soit haineux ou enthousiaste, devient une donn├®e valorisable, une monnaie dÔÇÖ├®change pour les plateformes. Plus une publication divise, plus elle capte lÔÇÖattentionÔÇª et plus elle rapporte.Ce dossier explore donc cette m├®canique de lÔÇÖopinion cliv├®e, en sÔÇÖappuyant sur des articles r├®dig├®s par des acteurs de terrain :\r\n<ul>\r\n 	<li><strong>Polarisation en ligne : lÔÇÖ├®conomie du discours ?┬á</strong>ÔÇô Brieuc Guffen ÔÇô M├®dia animation</li>\r\n 	<li><strong>De la discussion de comptoir aux r├®seaux sociaux : ├®volution des pratiques de d├®bats et de socialisation</strong>┬áÔÇô Fran├ºois Remy &amp; Damien Van Achter</li>\r\n 	<li><strong>50 nuances de palabres : Rep├®rer les arguments biais├®s, reconstruire le dialogue</strong>┬áÔÇô Alice Obee et Katia Derycke ÔÇô Picardie La├»que.</li>\r\n</ul>\r\nNous invitons les enseignant┬Àes, ├®ducateur┬Àtrices, animateur┬Àtrices et m├®diateur┬Àtrices ├á sÔÇÖemparer de ce dossier comme dÔÇÖun outil souple, permettant dÔÇÖouvrir la discussion, de nuancer les lectures, et dÔÇÖamener chacun┬Àe ├á r├®fl├®chir ├á ses propres usages num├®riques et informationnels. Sans imposer de r├®ponse unique, mais avec lÔÇÖintime conviction que la d├®mocratie a besoin de complexit├®, de dialogue, et de nuance.┬áBonne lecture, et surtout : bon d├®bat.'),(355,39,'_Builder_0_subsection_1_text','field_69c4d54bbf536'),(356,39,'Builder_0_subsection_1_persotext','0'),(357,39,'_Builder_0_subsection_1_persotext','field_69c4d8e087a6b'),(358,39,'Builder_0_subsection_2_paragraphename','Dossier p├®dagogique'),(359,39,'_Builder_0_subsection_2_paragraphename','field_69c72efc6a921'),(360,39,'Builder_0_subsection_3_iframe','http:////v.calameo.com/?bkcode=006349639a9508400e65b&language=fr&page=&showsharemenu=true&clickTo=public&clickTarget=_self&clickToUrl=&autoFlip=0&mode=mini&wmode=transparent'),(361,39,'_Builder_0_subsection_3_iframe','field_69c73cf3282d9'),(362,39,'Builder_0_subsection_0_alignbottom','1'),(363,39,'_Builder_0_subsection_0_alignbottom','field_69cbb95a00325'),(364,39,'Builder_0_subsection_0_aligntop','0'),(365,39,'_Builder_0_subsection_0_aligntop','field_69cbb98400326'),(382,40,'Builder','a:1:{i:0;s:10:\"subsection\";}'),(383,40,'_Builder','field_69aef24b28175'),(416,43,'Builder_0_subsection_0_videolink','https://www.youtube.com/watch?v=IUCRVF1WSZ8&t=1s'),(417,43,'_Builder_0_subsection_0_videolink','field_69c4cdb278524'),(418,43,'Builder_0_subsection_0_videotitle','Titre de la vid├®o'),(419,43,'_Builder_0_subsection_0_videotitle','field_69c4d22f9fcaa'),(420,43,'Builder_0_subsection_0_videotext','Texte d\'accompagnement de la vid├®o'),(421,43,'_Builder_0_subsection_0_videotext','field_69c4d26e9fcab'),(422,43,'Builder_0_subsection_0_displayvideotitle','0'),(423,43,'_Builder_0_subsection_0_displayvideotitle','field_69c4d2a89fcac'),(424,43,'Builder_0_subsection_0_displayvideotext','0'),(425,43,'_Builder_0_subsection_0_displayvideotext','field_69c4d2c99fcad'),(426,43,'Builder_0_subsection_1_text','JÔÇÖen peux plus de toutes ces news si d├®primantes qui disent tout et nÔÇÖimporte quoi ! Je r├¬ve dÔÇÖautre choseÔÇª JÔÇÖveux de la vraie info, des trucs qui me parlent, pas un d├®fil├® putaclicÔÇª\r\n\r\nLes m├®dias, sont vraiment libres ? Parfois jÔÇÖai des doutesÔÇª Et puis cÔÇÖest quoi la place des citoyens l├á-dedans ? Des gens comme toi et moiÔÇª\r\n\r\nFaudrait quÔÇÖon en parle ensemble, journalistes et citoyens r├®unisÔÇªquÔÇÖon se mette toutes et tous autour de la table pour avancer, parce que l├á, ├ºa urge !'),(427,43,'_Builder_0_subsection_1_text','field_69c4d54bbf536'),(428,43,'Builder_0_subsection_1_persotext','1'),(429,43,'_Builder_0_subsection_1_persotext','field_69c4d8e087a6b'),(430,43,'Builder_0_subsection','a:19:{i:0;s:9:\"videosolo\";i:1;s:8:\"textbloc\";i:2;s:15:\"paragraphetitle\";i:3;s:8:\"textbloc\";i:4;s:9:\"videosolo\";i:5;s:15:\"paragraphetitle\";i:6;s:8:\"textbloc\";i:7;s:9:\"videosolo\";i:8;s:15:\"paragraphetitle\";i:9;s:9:\"videosolo\";i:10;s:8:\"textbloc\";i:11;s:13:\"imagegallerie\";i:12;s:15:\"paragraphetitle\";i:13;s:8:\"textbloc\";i:14;s:6:\"iframe\";i:15;s:8:\"textbloc\";i:16;s:9:\"buttonpdf\";i:17;s:15:\"paragraphetitle\";i:18;s:8:\"textbloc\";}'),(431,43,'_Builder_0_subsection','field_69c4c745e4070'),(432,43,'Builder','a:1:{i:0;s:10:\"subsection\";}'),(433,43,'_Builder','field_69aef24b28175'),(434,43,'Builder_0_subsection_2_paragraphename','L\'├®mission radio !'),(435,43,'_Builder_0_subsection_2_paragraphename','field_69c72efc6a921'),(436,43,'Builder_0_subsection_3_text','<p class=\"wp-block-heading\">Mehdi prend les manettes des studios de YouFM !</p>'),(437,43,'_Builder_0_subsection_3_text','field_69c4d54bbf536'),(438,43,'Builder_0_subsection_3_persotext','0'),(439,43,'_Builder_0_subsection_3_persotext','field_69c4d8e087a6b'),(440,43,'Builder_0_subsection_4_videolink','https://www.youtube.com/watch?v=1ANqX0Rc0KI&t=11s'),(441,43,'_Builder_0_subsection_4_videolink','field_69c4cdb278524'),(442,43,'Builder_0_subsection_4_videotitle','Titre de la vid├®o'),(443,43,'_Builder_0_subsection_4_videotitle','field_69c4d22f9fcaa'),(444,43,'Builder_0_subsection_4_videotext','Texte d\'accompagnement de la vid├®o'),(445,43,'_Builder_0_subsection_4_videotext','field_69c4d26e9fcab'),(446,43,'Builder_0_subsection_4_displayvideotitle','0'),(447,43,'_Builder_0_subsection_4_displayvideotitle','field_69c4d2a89fcac'),(448,43,'Builder_0_subsection_4_displayvideotext','0'),(449,43,'_Builder_0_subsection_4_displayvideotext','field_69c4d2c99fcad'),(450,43,'Builder_0_subsection_5_paragraphename','La journ├®e ├®v├¿nement'),(451,43,'_Builder_0_subsection_5_paragraphename','field_69c72efc6a921'),(452,43,'Builder_0_subsection_6_text','<p data-start=\"0\" data-end=\"274\">Revivez cette journ├®e dÔÇÖ├®changes organis├®e au Mundaneum le 21 avril 2022, qui a rassembl├® jeunes et professionnels autour de questions essentielles : <em data-start=\"150\" data-end=\"274\">quÔÇÖest-ce quÔÇÖun m├®dia ? comment (re)construire la confiance envers les m├®dias ? quelle place pour le citoyen aujourdÔÇÖhui ?</em></p>\r\n<p data-start=\"276\" data-end=\"458\">Sans langue de bois, journalistes, formateurs┬Àtrices et expert┬Àes en ├®ducation aux m├®dias ont partag├® leurs points de vue et exp├®riences, ouvrant le dialogue avec les participant┬Àes.</p>\r\n<p data-start=\"460\" data-end=\"619\">Destin├®e aux 15-25 ans, cette rencontre a altern├® entre moments dÔÇÖ├®changes et ateliers pratiques, favorisant la r├®flexion critique et lÔÇÖexpression de chacun┬Àe.</p>'),(453,43,'_Builder_0_subsection_6_text','field_69c4d54bbf536'),(454,43,'Builder_0_subsection_6_persotext','0'),(455,43,'_Builder_0_subsection_6_persotext','field_69c4d8e087a6b'),(456,43,'Builder_0_subsection_7_videolink','https://www.youtube.com/watch?v=IauSKoQIgQ4&t=3325s'),(457,43,'_Builder_0_subsection_7_videolink','field_69c4cdb278524'),(458,43,'Builder_0_subsection_7_videotitle','Titre de la vid├®o'),(459,43,'_Builder_0_subsection_7_videotitle','field_69c4d22f9fcaa'),(460,43,'Builder_0_subsection_7_videotext','Texte d\'accompagnement de la vid├®o'),(461,43,'_Builder_0_subsection_7_videotext','field_69c4d26e9fcab'),(462,43,'Builder_0_subsection_7_displayvideotitle','0'),(463,43,'_Builder_0_subsection_7_displayvideotitle','field_69c4d2a89fcac'),(464,43,'Builder_0_subsection_7_displayvideotext','0'),(465,43,'_Builder_0_subsection_7_displayvideotext','field_69c4d2c99fcad'),(466,43,'Builder_0_subsection_8_paragraphename','Le cycle d\'atelier'),(467,43,'_Builder_0_subsection_8_paragraphename','field_69c72efc6a921'),(468,43,'Builder_0_subsection_9_videolink','https://www.youtube.com/watch?v=LHNQZj8qLOU&t=67s'),(469,43,'_Builder_0_subsection_9_videolink','field_69c4cdb278524'),(470,43,'Builder_0_subsection_9_videotitle','Titre de la vid├®o'),(471,43,'_Builder_0_subsection_9_videotitle','field_69c4d22f9fcaa'),(472,43,'Builder_0_subsection_9_videotext','Texte d\'accompagnement de la vid├®o'),(473,43,'_Builder_0_subsection_9_videotext','field_69c4d26e9fcab'),(474,43,'Builder_0_subsection_9_displayvideotitle','0'),(475,43,'_Builder_0_subsection_9_displayvideotitle','field_69c4d2a89fcac'),(476,43,'Builder_0_subsection_9_displayvideotext','0'),(477,43,'_Builder_0_subsection_9_displayvideotext','field_69c4d2c99fcad'),(478,43,'Builder_0_subsection_10_text','En partenariat avec Actions m├®dias jeunes, nous vous proposons des ateliers gratuits\r\n<ul>\r\n 	<li>Cr├®e ton m├®dia</li>\r\n 	<li>CÔÇÖest pas sourc├® !</li>\r\n</ul>\r\nAction M├®dias Jeunes propose aux participants de se plonger au c┼ôur de la fabrication de lÔÇÖinformation. Les jeunes sont divis├®s en plusieurs petits groupes et chaque groupe correspond ├á une r├®daction de presse ├®crite. Face ├á un fait dÔÇÖactualit├® cr├®├® de toutes pi├¿ces, chaque r├®daction a la lourde t├óche de faire des choix parmi les sources propos├®es afin de donner lÔÇÖinformation la plus pertinente ├á leurs lecteur┬Àrices. Mais attention, lÔÇÖinformation nÔÇÖattend pas et nos jeunes journalistes en herbe doivent apprendre ├á travailler sous la pression du temps, lÔÇÖennemi num├®ro un de lÔÇÖinformation v├®rifi├®e.\r\n\r\nCette animation tr├¿s concr├¿te am├¿ne les jeunes ├á une r├®flexion autour de la fiabilit├® de lÔÇÖinformation, du\r\nrecoupage des sources, des m├®dias dÔÇÖinformation en g├®n├®ral ainsi que sur la question des fake news.\r\nTrouver une bonne information sourc├®e, v├®rifi├®e et pertinente lors de nos recherches sur un sujet sp├®cifique nÔÇÖest pas toujours chose ais├®e. Ce jeu de soci├®t├® est lÔÇÖoccasion dÔÇÖamener une r├®flexion sur ces th├®matiques d├¿s le plus jeune ├óge afin dÔÇÖ├®veiller son esprit critique et dÔÇÖattraper les bons r├®flexes le plus t├┤t\r\npossible !\r\n\r\nA vivre en classe ou en groupe pour des jeunes de 15-25 ans\r\n\r\nPlus dÔÇÖinfos info@mundaneum.be'),(479,43,'_Builder_0_subsection_10_text','field_69c4d54bbf536'),(480,43,'Builder_0_subsection_10_persotext','0'),(481,43,'_Builder_0_subsection_10_persotext','field_69c4d8e087a6b'),(512,43,'Builder_0_subsection_11_gallerie','a:10:{i:0;s:3:\"169\";i:1;s:3:\"170\";i:2;s:3:\"171\";i:3;s:3:\"172\";i:4;s:3:\"173\";i:5;s:3:\"174\";i:6;s:3:\"175\";i:7;s:3:\"176\";i:8;s:3:\"177\";i:9;s:3:\"178\";}'),(513,43,'_Builder_0_subsection_11_gallerie','field_69cbd8829b23b'),(514,43,'Builder_0_subsection_11_affichagecaroussel','1'),(515,43,'_Builder_0_subsection_11_affichagecaroussel','field_69cbd8a19b23c'),(516,43,'Builder_0_subsection_11_affichagecanvas','0'),(517,43,'_Builder_0_subsection_11_affichagecanvas','field_69cbd9089b23d'),(518,43,'Builder_0_subsection_12_paragraphename','Dossier p├®dagogique'),(519,43,'_Builder_0_subsection_12_paragraphename','field_69c72efc6a921'),(522,43,'_oembed_4b4d748874ba02af806d6a254ec5b0a9','{{unknown}}'),(523,43,'Builder_0_subsection_13_text','Tous pourris ? Les m├®dias nous manipulent ? Pourquoi produisent-ils autant dÔÇÖinfos anxiog├¿nes ? Et quÔÇÖest-ce que je peux y faire moi en tant quÔÇÖenseignant, que parent ou que jeuneÔÇª en tant que citoyen ?'),(524,43,'_Builder_0_subsection_13_text','field_69c4d54bbf536'),(525,43,'Builder_0_subsection_13_persotext','0'),(526,43,'_Builder_0_subsection_13_persotext','field_69c4d8e087a6b'),(527,43,'Builder_0_subsection_14_iframe','http:////v.calameo.com/?bkcode=0063496395118feaceb08&language=fr&page=&showsharemenu=true&clickTo=public&clickTarget=_self&clickToUrl=&autoFlip=0&mode=mini&wmode=transparent'),(528,43,'_Builder_0_subsection_14_iframe','field_69c73cf3282d9'),(529,43,'Builder_0_subsection_15_text','Ce dossier p├®dagogique apporte des r├®ponses ├á ces questions en proposant une vision constructive et responsabilisante sans ├®luder les points dÔÇÖombre du journalisme contemporain et des m├®dias en Belgique.\r\n\r\nLa premi├¿re partie dresse le panorama des m├®dias en Belgique francophone. On y aborde la diversit├® des m├®dias existants mais aussi la concentration ├®conomique des grands titres de presse. On y explore ceux qui utilisent les r├®seaux sociaux pour produire des informations pertinentes mais aussi le financement de ceux-ci et lÔÇÖ├®conomie de lÔÇÖattention. La deuxi├¿me partie sÔÇÖint├®resse ├á la place du citoyen dans ces m├®dias. On y ├®voque les succ├¿s et aussi les ├®checs du ┬½journalisme participatif┬╗ avant de d├®crire dÔÇÖautres formes de journalisme int├®ressantes comme le ┬½journalisme constructif┬╗ ou le ┬½journalisme de solutions┬╗. Enfin, la troisi├¿me propose des ateliers ainsi quÔÇÖune biblioth├¿que de ressources qui vous permettront de questionner le fonctionnement des m├®dias actuels et la place des citoyens dans ceux-ci en classe, en famille ou entre amis.\r\n\r\nBonne lecture !'),(530,43,'_Builder_0_subsection_15_text','field_69c4d54bbf536'),(531,43,'Builder_0_subsection_15_persotext','0'),(532,43,'_Builder_0_subsection_15_persotext','field_69c4d8e087a6b'),(535,43,'Builder_0_subsection_1_ignorespacing','1'),(536,43,'_Builder_0_subsection_1_ignorespacing','field_69cbeb348ce06'),(537,43,'Builder_0_subsection_3_ignorespacing','0'),(538,43,'_Builder_0_subsection_3_ignorespacing','field_69cbeb348ce06'),(539,43,'Builder_0_subsection_6_ignorespacing','0'),(540,43,'_Builder_0_subsection_6_ignorespacing','field_69cbeb348ce06'),(541,43,'Builder_0_subsection_10_ignorespacing','0'),(542,43,'_Builder_0_subsection_10_ignorespacing','field_69cbeb348ce06'),(543,43,'Builder_0_subsection_13_ignorespacing','0'),(544,43,'_Builder_0_subsection_13_ignorespacing','field_69cbeb348ce06'),(545,43,'Builder_0_subsection_15_ignorespacing','0'),(546,43,'_Builder_0_subsection_15_ignorespacing','field_69cbeb348ce06'),(553,43,'couleur_sombre','#faac27'),(554,43,'_couleur_sombre','field_olthem_thm_couleur_sombre'),(555,41,'couleur_sombre','#ff44ae'),(556,41,'_couleur_sombre','field_olthem_thm_couleur_sombre'),(557,41,'Builder_0_subsection_1_ignorespacing','0'),(558,41,'_Builder_0_subsection_1_ignorespacing','field_69cbeb348ce06'),(559,41,'Builder_0_subsection_2_ignorespacing','0'),(560,41,'_Builder_0_subsection_2_ignorespacing','field_69cbeb348ce06'),(561,41,'Builder_0_subsection_4_ignorespacing','0'),(562,41,'_Builder_0_subsection_4_ignorespacing','field_69cbeb348ce06'),(563,41,'Builder_0_subsection_9_ignorespacing','0'),(564,41,'_Builder_0_subsection_9_ignorespacing','field_69cbeb348ce06'),(565,39,'couleur_sombre','#fc5f84'),(566,39,'_couleur_sombre','field_olthem_thm_couleur_sombre'),(567,39,'Builder_0_subsection_1_ignorespacing','0'),(568,39,'_Builder_0_subsection_1_ignorespacing','field_69cbeb348ce06'),(569,42,'couleur_sombre','#278d98'),(570,42,'_couleur_sombre','field_olthem_thm_couleur_sombre'),(571,42,'Builder','a:1:{i:0;s:10:\"subsection\";}'),(572,42,'_Builder','field_69aef24b28175'),(573,42,'Builder_0_subsection_0_videolink','https://www.youtube.com/watch?v=SX1KBbkX-mo'),(574,42,'_Builder_0_subsection_0_videolink','field_69c4cdb278524'),(575,42,'Builder_0_subsection_0_videotitle','Titre de la vid├®o'),(576,42,'_Builder_0_subsection_0_videotitle','field_69c4d22f9fcaa'),(577,42,'Builder_0_subsection_0_videotext','Texte d\'accompagnement de la vid├®o'),(578,42,'_Builder_0_subsection_0_videotext','field_69c4d26e9fcab'),(579,42,'Builder_0_subsection_0_displayvideotitle','0'),(580,42,'_Builder_0_subsection_0_displayvideotitle','field_69c4d2a89fcac'),(581,42,'Builder_0_subsection_0_displayvideotext','0'),(582,42,'_Builder_0_subsection_0_displayvideotext','field_69c4d2c99fcad'),(583,42,'Builder_0_subsection_1_text','Vous connaissez la derni├¿re ?\r\n\r\nJe serais ┬½┬ácomplotiste┬á┬╗ÔÇª Ouais, cÔÇÖest la r├®plique facile sur les r├®seaux sociaux quand on nÔÇÖa pas┬á dÔÇÖarguments ! Tout ├ºa parce que je vois les choses autrement et que jÔÇÖai pas envie de tout goberÔÇª JÔÇÖentends tout et son contraire, alors qui croire?\r\n\r\nApr├¿s tout, chacun a le droit de chercher sa v├®rit├®, non┬á?'),(584,42,'_Builder_0_subsection_1_text','field_69c4d54bbf536'),(585,42,'Builder_0_subsection_1_persotext','1'),(586,42,'_Builder_0_subsection_1_persotext','field_69c4d8e087a6b'),(587,42,'Builder_0_subsection_1_ignorespacing','0'),(588,42,'_Builder_0_subsection_1_ignorespacing','field_69cbeb348ce06'),(589,42,'Builder_0_subsection_2_text','┬½ Suis-je complotiste ? ┬╗ Voil├á la question que se pose Th├®o. Th├®o, il est un peu perdu car comme il le dit, il entend, il lit, toutÔÇª et son contraire. ├ça ne vous est jamais arriv├®, ├á vous, de sentir poindre des doutes, des questionnements et de vous dire que la version officielle nÔÇÖ├®tait peut-├¬tre pas la ÔÇ£vraieÔÇØ ? NÔÇÖavez-vous jamais dout├® ?\r\n\r\nChemtrails, illuminatis, terre plate, attentats du 11 septembre, complot jud├®o-ma├ºonnique, et plus r├®cemment, QAnon, le coronavirus et ses vaccinsÔÇªsont autant de sujets qui peuvent faire sourire, parfois, mais sur lesquels on peut vite en venir ├á sÔÇÖ├®charperÔÇªnotamment sur les r├®seaux sociaux.\r\n\r\nLe malaise que soul├¿ve le ph├®nom├¿ne des th├®ories du complot, toutes cat├®gories dÔÇÖ├óge confondues, r├®v├¿le surtout ├á quel point il est difficile de faire le tri dans la multitude dÔÇÖinformations que lÔÇÖon re├ºoit et combien il devient compliqu├® de se forger une opinion tout en respectant celles des autres.\r\n\r\nMais avoir un avis, finalement, en quoi est-ce si important ? Devons-nous vraiment en avoir un sur tout et surtout, le partager, et rapidement encore ? Quelles peuvent-├¬tre les cons├®quences de certaines croyances, dÔÇÖune m├®fiance accrue envers les discours officiels sur la d├®mocratie, lÔÇÖengagement citoyen, la sant├®, notre rapport aux m├®dias ?\r\n\r\nAu travers de ce projet et pour ce deuxi├¿me ├®pisode, nous souhaitons donner les cl├®s pour naviguer dans cet oc├®an de doutes sans jamais sÔÇÖy noyer, baliser le chemin de la construction de soi dans un rapport au monde qui ne soit pas teint├® dÔÇÖun scepticisme exacerb├®, sÔÇÖinterroger constamment sur les valeurs que lÔÇÖon cherche ├á d├®fendre, certes, mais porter une attention particuli├¿re ├á celles auxquelles dÔÇÖautres attachent de lÔÇÖimportance. Sans jugement. En privil├®giant, outre le dialogue entre soi et soi-m├¬me, celui entre soi et les autres.'),(590,42,'_Builder_0_subsection_2_text','field_69c4d54bbf536'),(591,42,'Builder_0_subsection_2_persotext','0'),(592,42,'_Builder_0_subsection_2_persotext','field_69c4d8e087a6b'),(593,42,'Builder_0_subsection_2_ignorespacing','0'),(594,42,'_Builder_0_subsection_2_ignorespacing','field_69cbeb348ce06'),(595,42,'Builder_0_subsection','a:17:{i:0;s:9:\"videosolo\";i:1;s:8:\"textbloc\";i:2;s:8:\"textbloc\";i:3;s:15:\"paragraphetitle\";i:4;s:8:\"textbloc\";i:5;s:9:\"videosolo\";i:6;s:15:\"paragraphetitle\";i:7;s:9:\"videosolo\";i:8;s:8:\"textbloc\";i:9;s:13:\"imagegallerie\";i:10;s:15:\"paragraphetitle\";i:11;s:8:\"textbloc\";i:12;s:15:\"paragraphetitle\";i:13;s:8:\"textbloc\";i:14;s:15:\"paragraphetitle\";i:15;s:6:\"iframe\";i:16;s:9:\"buttonpdf\";}'),(596,42,'_Builder_0_subsection','field_69c4c745e4070'),(597,42,'Builder_0_subsection_3_paragraphename','L\'├®mission radio !'),(598,42,'_Builder_0_subsection_3_paragraphename','field_69c72efc6a921'),(599,42,'Builder_0_subsection_4_text','Diffus├®e le 1er avril 2021, une ├®mission radio dÔÇÖune heure est propos├®e pour revenir sur les concepts de la th├®matique ! Son objectif? Baliser le projet et donner la parole ├á des intervenants travaillant le sujet. LÔÇÖ├®mission sera diffus├®e sur YouFM et sur nos r├®seaux sociaux !'),(600,42,'_Builder_0_subsection_4_text','field_69c4d54bbf536'),(601,42,'Builder_0_subsection_4_persotext','0'),(602,42,'_Builder_0_subsection_4_persotext','field_69c4d8e087a6b'),(603,42,'Builder_0_subsection_4_ignorespacing','0'),(604,42,'_Builder_0_subsection_4_ignorespacing','field_69cbeb348ce06'),(605,42,'Builder_0_subsection_5_videolink','https://www.youtube.com/watch?v=9N69DjRkxOs'),(606,42,'_Builder_0_subsection_5_videolink','field_69c4cdb278524'),(607,42,'Builder_0_subsection_5_videotitle','Titre de la vid├®o'),(608,42,'_Builder_0_subsection_5_videotitle','field_69c4d22f9fcaa'),(609,42,'Builder_0_subsection_5_videotext','Texte d\'accompagnement de la vid├®o'),(610,42,'_Builder_0_subsection_5_videotext','field_69c4d26e9fcab'),(611,42,'Builder_0_subsection_5_displayvideotitle','0'),(612,42,'_Builder_0_subsection_5_displayvideotitle','field_69c4d2a89fcac'),(613,42,'Builder_0_subsection_5_displayvideotext','0'),(614,42,'_Builder_0_subsection_5_displayvideotext','field_69c4d2c99fcad'),(648,42,'Builder_0_subsection_6_paragraphename','La journ├®e ├®v├¿nement'),(649,42,'_Builder_0_subsection_6_paragraphename','field_69c72efc6a921'),(650,42,'Builder_0_subsection_7_videolink','https://www.youtube.com/watch?v=5QuVRdGw7MY'),(651,42,'_Builder_0_subsection_7_