projets-labelises/mundaneum/\">Notre projet sur le site PCI</a>'),(1235,34,'_Builder_0_subsection_1_text','field_69c4d54bbf536'),(1236,34,'Builder_0_subsection_1_persotext','0'),(1237,34,'_Builder_0_subsection_1_persotext','field_69c4d8e087a6b'),(1238,34,'Builder_0_subsection_1_ignorespacing','0'),(1239,34,'_Builder_0_subsection_1_ignorespacing','field_69cbeb348ce06'),(1240,34,'Builder_0_subsection_2_gallerie','a:5:{i:0;s:3:\"210\";i:1;s:3:\"211\";i:2;s:3:\"212\";i:3;s:3:\"213\";i:4;s:3:\"214\";}'),(1241,34,'_Builder_0_subsection_2_gallerie','field_69cbd8829b23b'),(1242,34,'Builder_0_subsection_2_affichagecaroussel','0'),(1243,34,'_Builder_0_subsection_2_affichagecaroussel','field_69cbd8a19b23c'),(1244,34,'Builder_0_subsection_2_affichagecanvas','1'),(1245,34,'_Builder_0_subsection_2_affichagecanvas','field_69cbd9089b23d'),(1246,34,'Builder_0_subsection_3_innertitle','Web-documentaire'),(1247,34,'_Builder_0_subsection_3_innertitle','field_69d21e27eb888'),(1254,34,'Builder_0_subsection_5_videolink','https://www.youtube.com/watch?v=uqiM6VltWhI'),(1255,34,'_Builder_0_subsection_5_videolink','field_69c4cdb278524'),(1256,34,'Builder_0_subsection_5_videotitle','Th├®o d├®couvre les th├®ories du complot'),(1257,34,'_Builder_0_subsection_5_videotitle','field_69c4d22f9fcaa'),(1258,34,'Builder_0_subsection_5_videotext','Marie est sp├®cialiste des th├®ories du complotÔÇª jÔÇÖai ├®t├® lui poser 2,3 questionsÔÇª'),(1259,34,'_Builder_0_subsection_5_videotext','field_69c4d26e9fcab'),(1260,34,'Builder_0_subsection_5_displayvideotitle','1'),(1261,34,'_Builder_0_subsection_5_displayvideotitle','field_69c4d2a89fcac'),(1262,34,'Builder_0_subsection_5_displayvideotext','1'),(1263,34,'_Builder_0_subsection_5_displayvideotext','field_69c4d2c99fcad'),(1264,34,'Builder_0_subsection','a:14:{i:0;s:10:\"innertitle\";i:1;s:8:\"textbloc\";i:2;s:13:\"imagegallerie\";i:3;s:10:\"innertitle\";i:4;s:9:\"videosolo\";i:5;s:9:\"videosolo\";i:6;s:10:\"innertitle\";i:7;s:15:\"paragraphetitle\";i:8;s:8:\"textbloc\";i:9;s:15:\"paragraphetitle\";i:10;s:8:\"textbloc\";i:11;s:9:\"videosolo\";i:12;s:15:\"paragraphetitle\";i:13;s:8:\"textbloc\";}'),(1265,34,'_Builder_0_subsection','field_69c4c745e4070'),(1266,34,'Builder','a:1:{i:0;s:10:\"subsection\";}'),(1267,34,'_Builder','field_69aef24b28175'),(1314,34,'Builder_0_subsection_4_videolink','https://www.youtube.com/watch?v=L6w2-uKOdho'),(1315,34,'_Builder_0_subsection_4_videolink','field_69c4cdb278524'),(1316,34,'Builder_0_subsection_4_videotitle','Olga s\'interroge sur les algorithmes et les bulles de filtre'),(1317,34,'_Builder_0_subsection_4_videotitle','field_69c4d22f9fcaa'),(1318,34,'Builder_0_subsection_4_videotext','En naviguant sur Internet, jÔÇÖai trouv├® le nom de Victor : je vais aller lÔÇÖinterroger pour voir sÔÇÖil sait me d├®finir les algorithmes et bulles de filtres.'),(1319,34,'_Builder_0_subsection_4_videotext','field_69c4d26e9fcab'),(1320,34,'Builder_0_subsection_4_displayvideotitle','1'),(1321,34,'_Builder_0_subsection_4_displayvideotitle','field_69c4d2a89fcac'),(1322,34,'Builder_0_subsection_4_displayvideotext','1'),(1323,34,'_Builder_0_subsection_4_displayvideotext','field_69c4d2c99fcad'),(1324,34,'Builder_0_subsection_6_innertitle','Projets d├®j├á r├®alis├®s'),(1325,34,'_Builder_0_subsection_6_innertitle','field_69d21e27eb888'),(1326,34,'Builder_0_subsection_7_paragraphename','Et si on osait la paix sur les r├®seaux sociaux'),(1327,34,'_Builder_0_subsection_7_paragraphename','field_69c72efc6a921'),(1328,34,'Builder_0_subsection_8_text','<em>┬áA lÔÇÖheure o├╣ toute lÔÇÖinformation est partag├®e ├á lÔÇÖ├®chelle mondiale, quÔÇÖen est-il des id├®aux d├®fendus par les fondateurs du Mundaneum : le partage de la connaissance pour la paix ?</em>\r\n\r\nLe Mundaneum et la RTBF proposent en collaboration avec Action Cin├® M├®dia Jeunes une exp├®rience in├®dite aux 15 ÔÇô 22 ans en F├®d├®ration Wallonie-Bruxelles:\r\n\r\nAu coeur du ┬½┬áGoogle de papier┬á┬╗, partir ├á la d├®couverte dÔÇÖun moteur de recherche version ┬½┬á19├¿me si├¿cle┬á┬╗ ├á vocation pacifiste, mais aussi rencontrer les community managers de la RTBF ├á Reyers pour comprendre comment ils mod├¿rent les r├®seaux sociaux de la cha├«ne nationale francophone pour ├á la fin, produire une cha├«ne vid├®o sur le th├¿me #osonslapaix!\r\n\r\nLÔÇÖensemble des vid├®os seront diffus├®es sur les r├®seaux sociaux et projet├®es au Mundaneum ├á lÔÇÖoccasion dÔÇÖune grande soir├®e festive anim├®e par un journaliste de la RTBF.'),(1329,34,'_Builder_0_subsection_8_text','field_69c4d54bbf536'),(1330,34,'Builder_0_subsection_8_persotext','0'),(1331,34,'_Builder_0_subsection_8_persotext','field_69c4d8e087a6b'),(1332,34,'Builder_0_subsection_8_ignorespacing','0'),(1333,34,'_Builder_0_subsection_8_ignorespacing','field_69cbeb348ce06'),(1334,34,'Builder_0_subsection_9_paragraphename','On nous prend pour des C*** ! -D├®tricotons les th├®ories du complot'),(1335,34,'_Builder_0_subsection_9_paragraphename','field_69c72efc6a921'),(1336,34,'Builder_0_subsection_10_text','<em>Le syst├¿me est pourri, on ne nous dit pas toute la v├®rit├® !┬áLa terre est plate, je lÔÇÖai vu sur Youtube !</em>\r\n\r\n<em>Les m├®dias nous mentent sans arr├¬t !┬áSur Facebook, jÔÇÖai lu que des avions rejettent des produits chimiques dans le cielÔÇª</em>\r\n<em>Barack Obama et la Reine Elisabeth, ce sont des reptiliens!</em>\r\nVous avez peut-├¬tre d├®j├á entendu certaines de ces ┬½┬áv├®rit├®s┬á┬╗, ou lues sur les r├®seaux sociaux, peut-├¬tre aussi y croyez-vous fermement ? Si on se penche sur lÔÇÖunivers du secret ou┬áce qui est cach├® et d├®voil├® uniquement ├á ceux qui poss├¿dent les codes, arrive bien vite la question des th├®ories du complot et des fake news.\r\nEn marge de lÔÇÖexposition ÔÇ£<a href=\"http://expositions.mundaneum.org/fr/expositions/top-secret-xpo\" target=\"_blank\" rel=\"noreferrer noopener\">┬áTop Secret ! un monde ├á d├®crypter</a>ÔÇ£ qui se tient au Mundaneum jusquÔÇÖau 20 mai 2018, ┬ále Mundaneum et le Club de la Presse du Hainaut-Mons proposent un programme complet pour d├®tecter les m├®canismes des th├®ories du complot dans notre environnement du tout connect├®.┬á<strong>┬½┬áOn nous prend pour des c.. ?! D├®tricotons ensemble les th├®ories du complot!┬á┬╗</strong>┬ásÔÇÖadresse aux 15-25 ans, aux enseignants et ├á tout un chacun concern├® par lÔÇÖencadrement des jeunes en phase de questionnement.\r\n\r\n<strong>Le jeudi 8 f├®vrier 2018 a eu lieu une grande journ├®e au Mundaneum ├á Mons</strong>, pour ├®voquer, sans jouer les donneurs de le├ºon, cette th├®matique sensible.'),(1337,34,'_Builder_0_subsection_10_text','field_69c4d54bbf536'),(1338,34,'Builder_0_subsection_10_persotext','0'),(1339,34,'_Builder_0_subsection_10_persotext','field_69c4d8e087a6b'),(1340,34,'Builder_0_subsection_10_ignorespacing','0'),(1341,34,'_Builder_0_subsection_10_ignorespacing','field_69cbeb348ce06'),(1342,34,'Builder_0_subsection_11_videolink','https://www.youtube.com/watch?v=AWpGCIlAqcI&t=1s'),(1343,34,'_Builder_0_subsection_11_videolink','field_69c4cdb278524'),(1344,34,'Builder_0_subsection_11_videotitle','Titre de la vid├®o'),(1345,34,'_Builder_0_subsection_11_videotitle','field_69c4d22f9fcaa'),(1346,34,'Builder_0_subsection_11_videotext','Texte d\'accompagnement de la vid├®o'),(1347,34,'_Builder_0_subsection_11_videotext','field_69c4d26e9fcab'),(1348,34,'Builder_0_subsection_11_displayvideotitle','0'),(1349,34,'_Builder_0_subsection_11_displayvideotitle','field_69c4d2a89fcac'),(1350,34,'Builder_0_subsection_11_displayvideotext','0'),(1351,34,'_Builder_0_subsection_11_displayvideotext','field_69c4d2c99fcad'),(1352,34,'Builder_0_subsection_12_paragraphename','Apocalypse News : inventons le journalisme de demain !'),(1353,34,'_Builder_0_subsection_12_paragraphename','field_69c72efc6a921'),(1354,34,'Builder_0_subsection_13_text','<em>Tous les jours, on entend parler de fake news, de la m├®fiance envers les m├®diasÔÇª┬á</em><em>Et si, demain, il nÔÇÖy avait plus de journalistes, plus de presse ? Comment , d├¿s lors, ┬áfaire circuler les infos ? Quelles sont les alternatives ? Et surtout , quels sont les m├®dias dont nous r├¬vons pour le futur ?</em>\r\n\r\nLe projet<strong>┬áApocalypse News</strong>┬ápropose aux ├®tudiants de 15-25 ans dÔÇÖimaginer les m├®dias de demain !\r\n\r\nAu terme du projet 20 projets de m├®dias ont ├®t├® propos├® par les ├®tudiants, de quoi inspirer le journalisme de demain !'),(1355,34,'_Builder_0_subsection_13_text','field_69c4d54bbf536'),(1356,34,'Builder_0_subsection_13_persotext','0'),(1357,34,'_Builder_0_subsection_13_persotext','field_69c4d8e087a6b'),(1358,34,'Builder_0_subsection_13_ignorespacing','0'),(1359,34,'_Builder_0_subsection_13_ignorespacing','field_69cbeb348ce06'),(1360,40,'_oembed_3e614edefe08e1e1affffe3a47db6de8','<iframe title=\"Propagande &amp; m├®dias - Atelier - On n&#039;a que l&#039;info qu&#039;on se donne !\" width=\"640\" height=\"360\" src=\"https://www.youtube.com/embed/B_nxKa82xvY?feature=oembed\" frameborder=\"0\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe>'),(1361,40,'_oembed_time_3e614edefe08e1e1affffe3a47db6de8','1775736084'),(1364,218,'_edit_last','1'),(1365,218,'_edit_lock','1776352597:1'),(1366,220,'_edit_lock','1776440647:1'),(1367,220,'_edit_last','1'),(1368,222,'_edit_last','1'),(1369,222,'_edit_lock','1776656922:1'),(1370,218,'Builder_0_title','Inscription'),(1371,218,'_Builder_0_title','field_69aef38c28177'),(1372,218,'Builder_0_subtitle',''),(1373,218,'_Builder_0_subtitle','field_69aef3d228178'),(1374,218,'Builder_0_logo','1'),(1375,218,'_Builder_0_logo','field_69db8b0243b70'),(1376,218,'Builder_0_title_logo','icon_InfoHead_white'),(1377,218,'_Builder_0_title_logo','field_69db8b3c43b71'),(1378,218,'Builder','a:2:{i:0;s:5:\"title\";i:1;s:11:\"formbuilder\";}'),(1379,218,'_Builder','field_69aef24b28175'),(1380,219,'Builder_0_title','Inscription'),(1381,219,'_Builder_0_titl