osed','','logo_picardielaique','','','2026-04-01 17:32:00','2026-04-01 17:32:00','',38,'http://localhost:10010/wp-content/uploads/2026/03/logo_PicardieLaique.png',0,'attachment','image/png',0),(199,1,'2026-04-01 17:32:10','2026-04-01 17:32:10','','logo_M├®diaAnimation','','inherit','open','closed','','logo_mediaanimation','','','2026-04-01 17:32:24','2026-04-01 17:32:24','',38,'http://localhost:10010/wp-content/uploads/2026/03/logo_MediaAnimation.png',0,'attachment','image/png',0),(200,1,'2026-04-01 17:32:33','2026-04-01 17:32:33','','logo_YouFM','','inherit','open','closed','','logo_youfm','','','2026-04-01 17:32:44','2026-04-01 17:32:44','',38,'http://localhost:10010/wp-content/uploads/2026/03/logo_YouFM.png',0,'attachment','image/png',0),(201,1,'2026-04-02 09:16:27','2026-04-02 09:16:27','<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Who we are</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost:10010.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Comments</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitorÔÇÖs IP address and browser user agent string to help spam detection.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Media</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Cookies</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select \"Remember Me\", your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:paragraph -->\r\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\r\n<!-- /wp:paragraph -->\r\n\r\n<!-- wp:heading -->\r\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\r\n<!-- /wp:heading -->\r\n\r\n<!-- wp:paragraph -->\r\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\r\n<!-- /wp:paragraph -->\r\n<p>&nbsp;</p>','Mentions l├®gales','','inherit','closed','closed','','3-revision-v1','','','2026-04-02 09:16:27','2026-04-02 09:16:27','',3,'http://localhost:10010/?p=201',0,'revision','',0),(202,1,'2026-04-02 09:32:33','2026-04-02 09:32:33','<!-- wp:heading -->\n<h3 class=\"wp-block-heading\">1. G├®n├®ralit├®s</h3>\n<p>Ce site internet est g├®r├® par lÔÇÖasbl Mundaneum, association sans but lucratif, dont le si├¿ge social est ├®tabli ├á 7000 Mons rue des passages n┬░15, num├®ro dÔÇÖentreprise BCE .451.247.562.<br />Les pr├®sentes conditions sÔÇÖappliquent ├á lÔÇÖutilisation de┬á<a href=\"https://www.mundaneum.org/\">www.mundaneum.org</a>┬á(ci-apr├¿s d├®nomm├® le ┬½ site internet ┬╗). En acc├®dant au site internet et en lÔÇÖutilisant, vous vous engagez ├á accepter et ├á respecter ces conditions.</p>\n<h3 class=\"wp-block-heading\"><span id=\"2_Acces_au_site_internet_et_utilisation_du_site\" class=\"ez-toc-section\"></span>2. Acc├¿s au site internet et utilisation du site</h3>\n<p>Pour tout acc├¿s au site internet et toute utilisation du site, vous vous engagez ├á ne pas lÔÇÖutiliser ill├®galement, par exemple pour la transmission ou le postage de virus ou de mat├®riel ill├®gal ou ill├®gitime ou inappropri├®. Vous vous engagez ├®galement ├á ne pas utiliser le site internet ou des parties de ce site dÔÇÖune mani├¿re qui enfreindrait de quelconques droits tels que, entre autres, mais pas exclusivement, les droits de lÔÇÖasbl Mundaneum et de tiers dans le domaine de la propri├®t├® intellectuelle.</p>\n<h3 class=\"wp-block-heading\"><span id=\"3_Droits_de_propriete_intellectuelle\" class=\"ez-toc-section\"></span>3. Droits de propri├®t├® intellectuelle</h3>\n<p>Tous les logiciels, bases de donn├®es, textes, photos, films, images, donn├®es, d├®nominations, appellations commerciales, noms de domaine, marques, croquis, mod├¿les, logos et autres information figurant sur le site internet (les ┬½ informations ┬╗) sont prot├®g├®s par des droits intellectuels appartenant ├á lÔÇÖasbl Mundaneum ou ├á des tiers. Sans lÔÇÖaccord ├®crit pr├®alable de lÔÇÖasbl Mundaneum, il est interdit de reproduire les informations (hormis en cas de reproduction temporaire de nature transitoire ou occasionnelle dans le but dÔÇÖune utilisation l├®gitime, sans valeur ├®conomique ind├®pendante), de les modifier, de les publier, de les distribuer ou de les envoyer, de les vendre, de les mettre ├á disposition ou de les c├®der autrement ou dÔÇÖaccorder de quelconques droits ├á des tiers concernant ces informations. Les archives digitalis├®es pr├®sent├®es sur ce site sont les collections de la F├®d├®ration Wallonie-Bruxelles, en d├®p├┤t au Mundaneum, Mons.</p>\n<h3 class=\"wp-block-heading\"><span id=\"4_Responsabilite_de_lutilisateur\" class=\"ez-toc-section\"></span>4. Responsabilit├® de lÔÇÖutilisateur</h3>\n<p>En cas dÔÇÖinfraction ├á un quelconque autre droit du Mundaneum ou de tiers (en ce compris les partenaires de lÔÇÖasbl Mundaneum, les auteurs et ayants droit dÔÇÖinformations pr├®sent├®es sur le site internet) des suites de lÔÇÖutilisation de ce site internet ou de parties de ce site, vous devrez indemniser lÔÇÖasbl Mundaneum et tous les tiers et ├®galement les pr├®server de toute requ├¬te, de tout dommage ou de toute responsabilit├® de quelque nature que ce soit, y compris les dommages cons├®cutifs, qui en r├®sulteraient.</p>\n<h3 class=\"wp-block-heading\"><span id=\"5_Informations_sur_le_site_internet_et_communiquees_par_le_biais_dun_message\" class=\"ez-toc-section\"></span>5. Informations sur le site internet et communiqu├®es par le biais dÔÇÖun message</h3>\n<p>Il se peut que les informations qui sont propos├®es par le biais du site internet ou dÔÇÖun message soient erron├®es ou incompl├¿tes. LÔÇÖasbl Mundaneum met tout en ┼ôuvre pour travailler avec une pr├®cision optimale, mais ne garantit pas la justesse, la fiabilit├®, la ponctualit├®, la pr├®cision ou dÔÇÖautres propri├®t├®s des informations.┬á Les informations sont fournies sans quelque forme de garantie que ce soit. LÔÇÖasbl Mundaneum d├®cline toute responsabilit├® en cas de virus ou dÔÇÖautres informations qui pourraient porter pr├®judice ├á lÔÇÖutilisateur ou ├á des tiers et pour tout dommage que cela pourrait provoquer.</p>\n<h3 class=\"wp-block-heading\"><span id=\"6_Liens_vers_dautres_sites_internet\" class=\"ez-toc-section\"></span>6. Liens vers dÔÇÖautres sites internet</h3>\n<p>Le site internet peut contenir des liens vers des sites internet ou des pages internet de tiers ou y faire r├®f├®rence dÔÇÖune autre mani├¿re. LÔÇÖasbl Mundaneum nÔÇÖa aucun contr├┤le sur le contenu de ces sites internet ou pages internet et d├®cline toute responsabilit├® pour leur contenu ou leurs caract├®ristiques.┬á Le fait que lÔÇÖasbl Mundaneum place des liens nÔÇÖimplique aucunement lÔÇÖapprobation de leur contenu.</p>\n<h3 class=\"wp-block-heading\"><span id=\"7_Protection_de_la_vie_privee\" class=\"ez-toc-section\"></span>7. Protection de la vie priv├®e</h3>\n<p><a href=\"https://mundaneum.org/politique-de-protection-de-la-vie-privee/\">Voir notre politique de protection de la vie priv├®e</a></p>\n<h3 class=\"wp-block-heading\"><span id=\"8_Achat-vente_Billetterie\" class=\"ez-toc-section\"></span>8. Achat-vente &amp; Billetterie</h3>\n<p>Voir nos conditions de vente</p>\n<h3 class=\"wp-block-heading\"><span id=\"9_Legislation_applicable_et_tribunaux_competents\" class=\"ez-toc-section\"></span>9. L├®gislation applicable et tribunaux comp├®tents</h3>\n<p>La l├®gislation belge sÔÇÖapplique au site internet, ├á lÔÇÖexception dÔÇÖautres dispositions l├®gales de droit contraignant. En cas de litige, seuls les tribunaux de lÔÇÖarrondissement de Mons sont comp├®tents.</p>\n<h3 class=\"wp-block-heading\"><span id=\"10_Contact\" class=\"ez-toc-section\"></span>10. Contact</h3>\n<p>Asbl Mundaneum, association sans but lucratif,<br />15, rue des passages ÔÇô 7000 Mons<br />BCE .451.247.562<br />+32 (02) 65 31 53 43<br /><a href=\"mailto:info@mundaneum.be\">info@mundaneum.be</a></p>\n<p><br />Copyright ┬® 2026 asbl Mundaneum<br />Tous droits express├®ment r├®serv├®s</p>\n<!-- /wp:paragraph -->\n<p>&nbsp;</p>','Mentions l├®gales','','inherit','closed','closed','','3-autosave-v1','','','2026-04-02 09:32:33','2026-04-02 09:32:33','',3,'http://localhost:10010/?p=202',0,'revision','',0),(203,1,'2026-04-02 09:32:37','2026-04-02 09:32:37','<!-- wp:heading -->\r\n<h3 class=\"wp-block-heading\">1. G├®n├®ralit├®s</h3>\r\n<p>Ce site internet est g├®r├® par lÔÇÖasbl Mundaneum, association sans but lucratif, dont le si├¿ge social est ├®tabli ├á 7000 Mons rue des passages n┬░15, num├®ro dÔÇÖentreprise BCE .451.247.562.<br />Les pr├®sentes conditions sÔÇÖappliquent ├á lÔÇÖutilisation de┬á<a href=\"https://www.mundaneum.org/\">www.mundaneum.org</a>┬á(ci-apr├¿s d├®nomm├® le ┬½ site internet ┬╗). En acc├®dant au site internet et en lÔÇÖutilisant, vous vous engagez ├á accepter et ├á respecter ces conditions.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"2_Acces_au_site_internet_et_utilisation_du_site\" class=\"ez-toc-section\"></span>2. Acc├¿s au site internet et utilisation du site</h3>\r\n<p>Pour tout acc├¿s au site internet et toute utilisation du site, vous vous engagez ├á ne pas lÔÇÖutiliser ill├®galement, par exemple pour la transmission ou le postage de virus ou de mat├®riel ill├®gal ou ill├®gitime ou inappropri├®. Vous vous engagez ├®galement ├á ne pas utiliser le site internet ou des parties de ce site dÔÇÖune mani├¿re qui enfreindrait de quelconques droits tels que, entre autres, mais pas exclusivement, les droits de lÔÇÖasbl Mundaneum et de tiers dans le domaine de la propri├®t├® intellectuelle.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"3_Droits_de_propriete_intellectuelle\" class=\"ez-toc-section\"></span>3. Droits de propri├®t├® intellectuelle</h3>\r\n<p>Tous les logiciels, bases de donn├®es, textes, photos, films, images, donn├®es, d├®nominations, appellations commerciales, noms de domaine, marques, croquis, mod├¿les, logos et autres information figurant sur le site internet (les ┬½ informations ┬╗) sont prot├®g├®s par des droits intellectuels appartenant ├á lÔÇÖasbl Mundaneum ou ├á des tiers. Sans lÔÇÖaccord ├®crit pr├®alable de lÔÇÖasbl Mundaneum, il est interdit de reproduire les informations (hormis en cas de reproduction temporaire de nature transitoire ou occasionnelle dans le but dÔÇÖune utilisation l├®gitime, sans valeur ├®conomique ind├®pendante), de les modifier, de les publier, de les distribuer ou de les envoyer, de les vendre, de les mettre ├á disposition ou de les c├®der autrement ou dÔÇÖaccorder de quelconques droits ├á des tiers concernant ces informations. Les archives digitalis├®es pr├®sent├®es sur ce site sont les collections de la F├®d├®ration Wallonie-Bruxelles, en d├®p├┤t au Mundaneum, Mons.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"4_Responsabilite_de_lutilisateur\" class=\"ez-toc-section\"></span>4. Responsabilit├® de lÔÇÖutilisateur</h3>\r\n<p>En cas dÔÇÖinfraction ├á un quelconque autre droit du Mundaneum ou de tiers (en ce compris les partenaires de lÔÇÖasbl Mundaneum, les auteurs et ayants droit dÔÇÖinformations pr├®sent├®es sur le site internet) des suites de lÔÇÖutilisation de ce site internet ou de parties de ce site, vous devrez indemniser lÔÇÖasbl Mundaneum et tous les tiers et ├®galement les pr├®server de toute requ├¬te, de tout dommage ou de toute responsabilit├® de quelque nature que ce soit, y compris les dommages cons├®cutifs, qui en r├®sulteraient.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"5_Informations_sur_le_site_internet_et_communiquees_par_le_biais_dun_message\" class=\"ez-toc-section\"></span>5. Informations sur le site internet et communiqu├®es par le biais dÔÇÖun message</h3>\r\n<p>Il se peut que les informations qui sont propos├®es par le biais du site internet ou dÔÇÖun message soient erron├®es ou incompl├¿tes. LÔÇÖasbl Mundaneum met tout en ┼ôuvre pour travailler avec une pr├®cision optimale, mais ne garantit pas la justesse, la fiabilit├®, la ponctualit├®, la pr├®cision ou dÔÇÖautres propri├®t├®s des informations.┬á Les informations sont fournies sans quelque forme de garantie que ce soit. LÔÇÖasbl Mundaneum d├®cline toute responsabilit├® en cas de virus ou dÔÇÖautres informations qui pourraient porter pr├®judice ├á lÔÇÖutilisateur ou ├á des tiers et pour tout dommage que cela pourrait provoquer.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"6_Liens_vers_dautres_sites_internet\" class=\"ez-toc-section\"></span>6. Liens vers dÔÇÖautres sites internet</h3>\r\n<p>Le site internet peut contenir des liens vers des sites internet ou des pages internet de tiers ou y faire r├®f├®rence dÔÇÖune autre mani├¿re. LÔÇÖasbl Mundaneum nÔÇÖa aucun contr├┤le sur le contenu de ces sites internet ou pages internet et d├®cline toute responsabilit├® pour leur contenu ou leurs caract├®ristiques.┬á Le fait que lÔÇÖasbl Mundaneum place des liens nÔÇÖimplique aucunement lÔÇÖapprobation de leur contenu.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"7_Protection_de_la_vie_privee\" class=\"ez-toc-section\"></span>7. Protection de la vie priv├®e</h3>\r\n<p><a href=\"https://mundaneum.org/politique-de-protection-de-la-vie-privee/\">Voir notre politique de protection de la vie priv├®e</a></p>\r\n<h3 class=\"wp-block-heading\"><span id=\"8_Achat-vente_Billetterie\" class=\"ez-toc-section\"></span>8. Achat-vente &amp; Billetterie</h3>\r\n<p>Voir nos conditions de vente</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"9_Legislation_applicable_et_tribunaux_competents\" class=\"ez-toc-section\"></span>9. L├®gislation applicable et tribunaux comp├®tents</h3>\r\n<p>La l├®gislation belge sÔÇÖapplique au site internet, ├á lÔÇÖexception dÔÇÖautres dispositions l├®gales de droit contraignant. En cas de litige, seuls les tribunaux de lÔÇÖarrondissement de Mons sont comp├®tents.</p>\r\n<h3 class=\"wp-block-heading\"><span id=\"10_Contact\" class=\"ez-toc-section\"></span>10. Contact</h3>\r\n<p>Asbl Mundaneum, association sans but lucratif,<br />15, rue des passages ÔÇô 7000 Mons<br />BCE .451.247.562<br />+32 (02) 65 31 53 43<br /><a href=\"mailto:info@mundaneum.be\">info@mundaneum.be</a></p>\r\n<p><br />Copyright ┬® 2026 asbl Mundaneum<br />Tous droits express├®ment r├®serv├®s</p>\r\n<!-- /wp:paragraph -->\r\n<p>&nbsp;</p>','Mentions l├®gales','','inherit','closed','closed','','3-revision-v1','','','2026-04-02 09:32:37','2026-04-02 09:32:37','',3,'http://localhost:10010/?p=203',0,'revision','',0),(204,1,'2026-04-02 14:43:37','2026-04-02 14:43:37','a:17:{s:10:\"aria-label\";s:0:\"\";s:4:\"type\";s:5:\"image\";s:12:\"instructions\";s:0:\"\";s:8:\"required\";i:0;s:17:\"conditional_logic\";i:0;s:7:\"wrapper\";a:3:{s:5:\"width\";s:0:\"\";s:5:\"class\";s:0:\"\";s:2:\"id\";s:0:\"\";}s:13:\"parent_layout\";s:20:\"layout_69ce802eba450\";s:13:\"return_format\";s:3:\"url\";s:7:\"library\";s:3:\"all\";s:9:\"min_width\";s:0:\"\";s:10:\"min_height\";s:0:\"\";s:8:\"min_size\";s:0:\"\";s:9:\"max_width\";s:0:\"\";s:10:\"max_height\";s:0:\"\";s:8:\"max_size\";s:0:\"\";s:10:\"mime_types\";s:0:\"\";s:12:\"preview_size\";s:6:\"medium\";}','Image','image','publish','closed','closed','','field_69ce8036ba452','','','2026-04-02 14:43:37','2026-04-02 14:43:37','',15,'http://localhost:10010/?post_type=acf-field&p=204',0,'acf-field','',0),(205,1,'2026-04-02 14